/** The facility at a glance — GET /api/v1/facility/summary (who may call: holders of facility.view). */
export function summaryFacility(): Promise<FacilitySummaryOut> {
  return api<FacilitySummaryOut>("GET", `/facility/summary`, undefined);
}

/** The equipment inventory — GET /api/v1/facility/equipment (who may call: holders of facility.view or facility.equipment.manage or facility.maintenance.record). */
export function listEquipment(query?: { medical_only?: boolean; department_id?: number | null; overdue_only?: boolean; include_disposed?: boolean }): Promise<EquipmentOut[]> {
  return api<EquipmentOut[]>("GET", withQuery(`/facility/equipment`, query), undefined);
}

/** One item: its record, plans, visits and licences — GET /api/v1/facility/equipment/{asset_id} (who may call: holders of facility.view or facility.equipment.manage or facility.maintenance.record). */
export function getEquipment(asset_id: number): Promise<EquipmentDetailOut> {
  return api<EquipmentDetailOut>("GET", `/facility/equipment/${asset_id}`, undefined);
}

/** Write the equipment off — POST /api/v1/facility/equipment/{asset_id}/dispose (who may call: holders of facility.equipment.dispose). */
export function dispose(asset_id: number, body: DisposeIn): Promise<EquipmentDetailOut> {
  return api<EquipmentDetailOut>("POST", `/facility/equipment/${asset_id}/dispose`, body);
}

/** The compliance register — GET /api/v1/facility/compliance-documents (who may call: holders of facility.view or facility.compliance.manage or blood.bank.manage). */
export function listDocumentsFacilityCompliance(query?: { kind?: "Licence" | "Registration" | "Certificate" | "Plan" | "Law" | null; category?: "Hospital" | "Radiation" | "Building" | "Fire" | "Lift" | "Boiler" | "Power" | "BloodTransfusion" | "Food" | "Waste" | "Pharmacy" | "Laboratory" | "Water" | "Environment" | "Emergency" | "Equipment" | "Staff" | "Other" | null; state?: "Valid" | "DueForRenewal" | "Expired" | "NoExpiry" | null; responsible_user_id?: number | null; include_closed?: boolean }): Promise<ComplianceDocumentOut[]> {
  return api<ComplianceDocumentOut[]>("GET", withQuery(`/facility/compliance-documents`, query), undefined);
}

/** The register to print (PDF) — GET /api/v1/facility/compliance-documents/register/pdf (who may call: holders of facility.view or facility.compliance.manage). */
export function registerPdfFacilityComplianceDocuments(): Promise<unknown> {
  return api<unknown>("GET", `/facility/compliance-documents/register/pdf`, undefined);
}

/** Drill coverage by department and shift — GET /api/v1/facility/drills/coverage (who may call: holders of facility.view or facility.drill.manage). */
export function coverage(): Promise<DrillCoverageOut> {
  return api<DrillCoverageOut>("GET", `/facility/drills/coverage`, undefined);
}

/** The written equipment plan and maintenance schedule (PDF) — GET /api/v1/facility/equipment/plan/pdf (who may call: holders of facility.view or facility.equipment.manage or facility.maintenance.record). */
export function equipmentPlanPdf(): Promise<unknown> {
  return api<unknown>("GET", `/facility/equipment/plan/pdf`, undefined);
}
